1	package keymap
2	
3	import (
4		"go/ast"
5		"go/parser"
6		"go/token"
7		"path/filepath"
8		"strconv"
9		"testing"
10	)
11	
12	// DEVDESK-279: bubbletea v2 gives tea.KeyPressMsg (and tea.Key) the fields
13	// Code, Text and Mod. Production code reads a key through String() only
14	// (DEVDESK-200), so those fields are refused too. legacy_key_scan_test.go covers
15	// the v1-only fields; this file covers the v2 ones.
16	//
17	// The scanner is syntactic like its siblings (no go/types). A read X.Code,
18	// X.Text or X.Mod is flagged when X is, within the same top-level declaration:
19	//   - an identifier declared with type tea.KeyPressMsg / tea.Key (parameter,
20	//     result, receiver, var, struct field is NOT tracked),
21	//   - an identifier assigned from a type assertion to one of those types,
22	//   - the binding of a type switch having a case with one of those types,
23	//   - an identifier assigned from a composite literal of one of those types,
24	//   - or a type assertion / conversion / composite literal used directly.
25	//
26	// Known limits: tracking is by name inside one top-level declaration, so a
27	// shadowing name of another type reused there could be a false positive, and a
28	// key reached through a struct field or a function result is not seen. Other
29	// types with Code/Text/Mod (project structs, textinput) are not flagged.
30	
31	var keyValueTypes = map[string]bool{"KeyPressMsg": true, "Key": true}
32	
33	// isKeyType reports whether e names tea.KeyPressMsg or tea.Key (optionally behind a pointer).
34	func isKeyType(e ast.Expr, teaName string) bool {
35		if star, ok := e.(*ast.StarExpr); ok {
36			e = star.X
37		}
38		sel, ok := e.(*ast.SelectorExpr)
39		if !ok {
40			return false
41		}
42		id, ok := sel.X.(*ast.Ident)
43		return ok && id.Name == teaName && keyValueTypes[sel.Sel.Name]
44	}
45	
46	// keyValued reports whether e is an expression that evidently has a key type:
47	// m.(tea.KeyPressMsg), tea.KeyPressMsg{...}, tea.Key(x).
48	func keyValued(e ast.Expr, teaName string) bool {
49		switch v := e.(type) {
50		case *ast.ParenExpr:
51			return keyValued(v.X, teaName)
52		case *ast.TypeAssertExpr:
53			return v.Type != nil && isKeyType(v.Type, teaName)
54		case *ast.CompositeLit:
55			return v.Type != nil && isKeyType(v.Type, teaName)
56		case *ast.CallExpr:
57			return isKeyType(v.Fun, teaName)
58		}
59		return false
60	}
61	
62	// keyNames collects the identifiers of one declaration that hold a key value.
63	func keyNames(decl ast.Decl, teaName string) map[string]bool {
64		names := map[string]bool{}
65		addFields := func(fl *ast.FieldList) {
66			if fl == nil {
67				return
68			}
69			for _, f := range fl.List {
70				if isKeyType(f.Type, teaName) {
71					for _, n := range f.Names {
72						names[n.Name] = true
73					}
74				}
75			}
76		}
77		ast.Inspect(decl, func(n ast.Node) bool {
78			switch v := n.(type) {
79			case *ast.FuncDecl:
80				addFields(v.Recv)
81				addFields(v.Type.Params)
82				addFields(v.Type.Results)
83			case *ast.FuncLit:
84				addFields(v.Type.Params)
85				addFields(v.Type.Results)
86			case *ast.ValueSpec:
87				if v.Type != nil && isKeyType(v.Type, teaName) {
88					for _, id := range v.Names {
89						names[id.Name] = true
90					}
91				}
92				for i, val := range v.Values {
93					if i < len(v.Names) && keyValued(val, teaName) {
94						names[v.Names[i].Name] = true
95					}
96				}
97			case *ast.AssignStmt:
98				// x := m.(tea.KeyPressMsg) and x, ok := m.(tea.KeyPressMsg)
99				if len(v.Rhs) == 1 && len(v.Lhs) > 0 && keyValued(v.Rhs[0], teaName) {
100					if id, ok := v.Lhs[0].(*ast.Ident); ok {
101						names[id.Name] = true
102					}
103				}
104				if len(v.Lhs) == len(v.Rhs) {
105					for i, r := range v.Rhs {
106						if id, ok := v.Lhs[i].(*ast.Ident); ok && keyValued(r, teaName) {
107							names[id.Name] = true
108						}
109					}
110				}
111			case *ast.TypeSwitchStmt:
112				as, ok := v.Assign.(*ast.AssignStmt)
113				if !ok || len(as.Lhs) != 1 {
114					break
115				}
116				id, ok := as.Lhs[0].(*ast.Ident)
117				if !ok {
118					break
119				}
120				for _, c := range v.Body.List {
121					for _, t := range c.(*ast.CaseClause).List {
122						if isKeyType(t, teaName) {
123							names[id.Name] = true
124						}
125					}
126				}
127			}
128			return true
129		})
130		return names
131	}
132	
133	// keyPressFieldReads returns "path:line field" for every read of a v2 key field.
134	func keyPressFieldReads(fset *token.FileSet, path string, file *ast.File, teaName string) []string {
135		if teaName == "" {
136			return nil
137		}
138		var out []string
139		for _, decl := range file.Decls {
140			names := keyNames(decl, teaName)
141			ast.Inspect(decl, func(n ast.Node) bool {
142				sel, ok := n.(*ast.SelectorExpr)
143				if !ok {
144					return true
145				}
146				switch sel.Sel.Name {
147				case "Code", "Text", "Mod":
148				default:
149					return true
150				}
151				x := sel.X
152				for {
153					p, ok := x.(*ast.ParenExpr)
154					if !ok {
155						break
156					}
157					x = p.X
158				}
159				hit := keyValued(x, teaName)
160				if id, ok := x.(*ast.Ident); ok && names[id.Name] {
161					hit = true
162				}
163				if hit {
164					out = append(out, filepath.ToSlash(path)+":"+strconv.Itoa(fset.Position(sel.Sel.Pos()).Line)+" ."+sel.Sel.Name)
165				}
166				return true
167			})
168		}
169		return out
170	}
171	
172	func TestKeyPressFieldReadsDetector(t *testing.T) {
173		const head = "package p\nimport tea \"charm.land/bubbletea/v2\"\n"
174		tests := []struct {
175			name string
176			src  string
177			want int
178		}{
179			// Faulty reads: the guard must see them.
180			{"code on a parameter", head + "func f(msg tea.KeyPressMsg) bool { return msg.Code == 'a' }\n", 1},
181			{"text on a parameter", head + "func f(msg tea.KeyPressMsg) string { return msg.Text }\n", 1},
182			{"mod on a parameter", head + "func f(msg tea.KeyPressMsg) bool { return msg.Mod != 0 }\n", 1},
183			{"tea.Key parameter", head + "func f(k tea.Key) rune { return k.Code }\n", 1},
184			{"pointer parameter", head + "func f(k *tea.Key) rune { return k.Code }\n", 1},
185			{"receiver", head + "type m struct{}\nfunc (m) f(k tea.KeyPressMsg) string { return k.Text }\n", 1},
186			{"type switch binding", head + "func f(m tea.Msg) rune {\n\tswitch k := m.(type) {\n\tcase tea.KeyPressMsg:\n\t\treturn k.Code\n\t}\n\treturn 0\n}\n", 1},
187			{"assertion binding", head + "func f(m tea.Msg) string {\n\tk, ok := m.(tea.KeyPressMsg)\n\tif !ok {\n\t\treturn \"\"\n\t}\n\treturn k.Text\n}\n", 1},
188			{"direct assertion", head + "func f(m tea.Msg) rune { return m.(tea.KeyPressMsg).Code }\n", 1},
189			{"var declaration", head + "func f() rune {\n\tvar k tea.KeyPressMsg\n\treturn k.Code\n}\n", 1},
190			{"composite literal binding", head + "func f() string {\n\tk := tea.KeyPressMsg{}\n\treturn k.Text\n}\n", 1},
191			{"closure parameter", head + "var g = func(k tea.KeyPressMsg) string { return k.Text }\n", 1},
192			{"aliased import", "package p\nimport bt \"charm.land/bubbletea/v2\"\nfunc f(k bt.KeyPressMsg) rune { return k.Code }\n", 1},
193			{"two fields", head + "func f(k tea.KeyPressMsg) bool { return k.Code == 'a' && k.Mod == 0 }\n", 2},
194			// Allowed or unrelated: no finding.
195			{"String", head + "func f(k tea.KeyPressMsg) string { return k.String() }\n", 0},
196			{"project struct", head + "type C struct{ Code int; Text string; Mod int }\nfunc f(c C) int { return c.Code + c.Mod + len(c.Text) }\n", 0},
197			{"project struct beside a key", head + "type C struct{ Code int }\nfunc f(c C, k tea.KeyPressMsg) int { _ = k.String(); return c.Code }\n", 0},
198			{"key literal field name", head + "var _ = tea.KeyPressMsg{Code: 'a', Text: \"a\"}\n", 0},
199			{"paste message", head + "func f(p tea.PasteMsg) string { return p.Content }\n", 0},
200			{"no bubbletea import", "package p\nfunc f(k struct{ Code int }) int { return k.Code }\n", 0},
201		}
202		for _, tc := range tests {
203			t.Run(tc.name, func(t *testing.T) {
204				fset := token.NewFileSet()
205				file, err := parser.ParseFile(fset, "x.go", tc.src, 0)
206				if err != nil {
207					t.Fatalf("parse: %v", err)
208				}
209				got := keyPressFieldReads(fset, "x.go", file, teaImportName(file))
210				if len(got) != tc.want {
211					t.Errorf("findings = %v, want %d", got, tc.want)
212				}
213			})
214		}
215	}
216	
217	func TestNoProductionCodeReadsKeyPressFields(t *testing.T) {
218		files := 0
219		walkProduction(t, func(fset *token.FileSet, path string, file *ast.File) {
220			files++
221			for _, where := range keyPressFieldReads(fset, path, file, teaImportName(file)) {
222				t.Errorf("%s: reads a field of tea.KeyPressMsg/tea.Key; match msg.String() instead (DEVDESK-200, DEVDESK-279)", where)
223			}
224		})
225		if files == 0 {
226			t.Fatal("no production file scanned — the scan is broken, not the code")
227		}
