package keymap

import (
	"go/ast"
	"go/parser"
	"go/token"
	"path/filepath"
	"strconv"
	"testing"
)

// DEVDESK-279: bubbletea v2 gives tea.KeyPressMsg (and tea.Key) the fields
// Code, Text and Mod. Production code reads a key through String() only
// (DEVDESK-200), so those fields are refused too. legacy_key_scan_test.go covers
// the v1-only fields; this file covers the v2 ones.
//
// The scanner is syntactic like its siblings (no go/types). A read X.Code,
// X.Text or X.Mod is flagged when X is, within the same top-level declaration:
//   - an identifier declared with type tea.KeyPressMsg / tea.Key (parameter,
//     result, receiver, var, struct field is NOT tracked),
//   - an identifier assigned from a type assertion to one of those types,
//   - the binding of a type switch having a case with one of those types,
//   - an identifier assigned from a composite literal of one of those types,
//   - or a type assertion / conversion / composite literal used directly.
//
// Known limits: tracking is by name inside one top-level declaration, so a
// shadowing name of another type reused there could be a false positive, and a
// key reached through a struct field or a function result is not seen. Other
// types with Code/Text/Mod (project structs, textinput) are not flagged.

var keyValueTypes = map[string]bool{"KeyPressMsg": true, "Key": true}

// isKeyType reports whether e names tea.KeyPressMsg or tea.Key (optionally behind a pointer).
func isKeyType(e ast.Expr, teaName string) bool {
	if star, ok := e.(*ast.StarExpr); ok {
		e = star.X
	}
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	id, ok := sel.X.(*ast.Ident)
	return ok && id.Name == teaName && keyValueTypes[sel.Sel.Name]
}

// keyValued reports whether e is an expression that evidently has a key type:
// m.(tea.KeyPressMsg), tea.KeyPressMsg{...}, tea.Key(x).
func keyValued(e ast.Expr, teaName string) bool {
	switch v := e.(type) {
	case *ast.ParenExpr:
		return keyValued(v.X, teaName)
	case *ast.TypeAssertExpr:
		return v.Type != nil && isKeyType(v.Type, teaName)
	case *ast.CompositeLit:
		return v.Type != nil && isKeyType(v.Type, teaName)
	case *ast.CallExpr:
		return isKeyType(v.Fun, teaName)
	}
	return false
}

// keyNames collects the identifiers of one declaration that hold a key value.
func keyNames(decl ast.Decl, teaName string) map[string]bool {
	names := map[string]bool{}
	addFields := func(fl *ast.FieldList) {
		if fl == nil {
			return
		}
		for _, f := range fl.List {
			if isKeyType(f.Type, teaName) {
				for _, n := range f.Names {
					names[n.Name] = true
				}
			}
		}
	}
	ast.Inspect(decl, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			addFields(v.Recv)
			addFields(v.Type.Params)
			addFields(v.Type.Results)
		case *ast.FuncLit:
			addFields(v.Type.Params)
			addFields(v.Type.Results)
		case *ast.ValueSpec:
			if v.Type != nil && isKeyType(v.Type, teaName) {
				for _, id := range v.Names {
					names[id.Name] = true
				}
			}
			for i, val := range v.Values {
				if i < len(v.Names) && keyValued(val, teaName) {
					names[v.Names[i].Name] = true
				}
			}
		case *ast.AssignStmt:
			// x := m.(tea.KeyPressMsg) and x, ok := m.(tea.KeyPressMsg)
			if len(v.Rhs) == 1 && len(v.Lhs) > 0 && keyValued(v.Rhs[0], teaName) {
				if id, ok := v.Lhs[0].(*ast.Ident); ok {
					names[id.Name] = true
				}
			}
			if len(v.Lhs) == len(v.Rhs) {
				for i, r := range v.Rhs {
					if id, ok := v.Lhs[i].(*ast.Ident); ok && keyValued(r, teaName) {
						names[id.Name] = true
					}
				}
			}
		case *ast.TypeSwitchStmt:
			as, ok := v.Assign.(*ast.AssignStmt)
			if !ok || len(as.Lhs) != 1 {
				break
			}
			id, ok := as.Lhs[0].(*ast.Ident)
			if !ok {
				break
			}
			for _, c := range v.Body.List {
				for _, t := range c.(*ast.CaseClause).List {
					if isKeyType(t, teaName) {
						names[id.Name] = true
					}
				}
			}
		}
		return true
	})
	return names
}

// keyPressFieldReads returns "path:line field" for every read of a v2 key field.
func keyPressFieldReads(fset *token.FileSet, path string, file *ast.File, teaName string) []string {
	if teaName == "" {
		return nil
	}
	var out []string
	for _, decl := range file.Decls {
		names := keyNames(decl, teaName)
		ast.Inspect(decl, func(n ast.Node) bool {
			sel, ok := n.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			switch sel.Sel.Name {
			case "Code", "Text", "Mod":
			default:
				return true
			}
			x := sel.X
			for {
				p, ok := x.(*ast.ParenExpr)
				if !ok {
					break
				}
				x = p.X
			}
			hit := keyValued(x, teaName)
			if id, ok := x.(*ast.Ident); ok && names[id.Name] {
				hit = true
			}
			if hit {
				out = append(out, filepath.ToSlash(path)+":"+strconv.Itoa(fset.Position(sel.Sel.Pos()).Line)+" ."+sel.Sel.Name)
			}
			return true
		})
	}
	return out
}

